const b = $json.body || {};
const missing = [];
if (!b.clinic_id) missing.push('clinic_id');
if (!b.patient_name || b.patient_name.trim().length < 2) missing.push('patient_name');
if (!b.phone || b.phone.trim().length < 8) missing.push('phone');
if (!b.appointmentDate || !/^\d{4}-\d{2}-\d{2}$/.test(b.appointmentDate)) missing.push('appointmentDate');
if (!b.appointmentTime) missing.push('appointmentTime');
if (!b.provider_event_id) missing.push('provider_event_id');

if (missing.length > 0) {
  return [{ json: { is_valid: false, message: `Missing or invalid required fields: ${missing.join(', ')}` } }];
}
return [{ json: { is_valid: true, body: b } }];

const reqDate = $('Inbound Test Webhook').item.json.body.appointmentDate;
const reqTimeStr = $('Inbound Test Webhook').item.json.body.appointmentTime;
const slots = $json.result?.data || [];
const tz = $('Validate Test Clinic').item.json.timezone || 'America/New_York';

const match = reqTimeStr.trim().match(/^(\d{1,2}):(\d{2})(?:\s*([AP]M))?$/i);
if (!match) return [{ json: { slot_found: false, message: 'Invalid time format. Use HH:MM AM/PM' } }];
let reqH = parseInt(match[1], 10);
const reqM = parseInt(match[2], 10);
const mer = match[3] ? match[3].toUpperCase() : null;
if (mer === 'PM' && reqH < 12) reqH += 12;
if (mer === 'AM' && reqH === 12) reqH = 0;

const dtf = new Intl.DateTimeFormat('en-US', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false
});

const matchedSlot = slots.find(s => {
  const parts = Object.fromEntries(dtf.formatToParts(new Date(s.starts_at)).map(p => [p.type, p.value]));
  const slotDate = `${parts.year}-${parts.month}-${parts.day}`;
  const slotH = parseInt(parts.hour, 10);
  const slotM = parseInt(parts.minute, 10);
  return slotDate === reqDate && slotH === reqH && slotM === reqM;
});

if (!matchedSlot) return [{ json: { slot_found: false, requested_date: reqDate, requested_time: reqTimeStr } }];

return [{
  json: {
    slot_found: true,
    starts_at: matchedSlot.starts_at,
    ends_at: matchedSlot.ends_at,
    duration_minutes: matchedSlot.duration_minutes,
    buffer_minutes: matchedSlot.buffer_minutes
  }
}];
